def gaussian_elimination(A):
    n = len(A)
    for i in range(n):
        # Find pivot row
        max_row = i
        for r in range(i+1, n):
            if abs(A[r][i]) > abs(A[max_row][i]):
                max_row = r
        A[i], A[max_row] = A[max_row], A[i]

        # Eliminate entries below the pivot
        factor = A[i][i]
        for j in range(i, n):
            A[i][j] /= factor
        for r in range(i+1, n):
            factor = A[r][i]
            for j in range(i, n):
                A[r][j] -= factor * A[i][j]

def matrix_multiplication(A, B):
    m = len(A)
    n = len(B[0])
    p = len(B)
    C = [[Fraction(0) for _ in range(n)] for _ in range(m)]
    for i in range(m):
        for j in range(n):
            for k in range(p):
                C[i][j] += A[i][k] * B[k][j]
    return C

def determinant(A):
    n = len(A)
    if n == 1:
        return A[0][0]
    det = Fraction(0)
    sign = Fraction(1, 1)
    for j in range(n):
        submatrix = [row[:j] + row[j+1:] for row in A[1:]]
